public int gcd(int a, int b) {
    while (b != 0) {
        int r = a % b; // gcd(a, b) = gcd(b, a mod b)
        a = b;
        b = r;
    }
    return a; // gcd(a, 0) = a
}

function countPrimes(n) {
  if (n < 3) return 0; // no primes below 2
  const isPrime = new Array(n).fill(true);
  isPrime[0] = isPrime[1] = false;
  for (let p = 2; p * p < n; p++) {
    if (!isPrime[p]) continue; // p is composite: its multiples are already crossed out
    for (let m = p * p; m < n; m += p) {
      isPrime[m] = false; // smaller multiples were crossed out by smaller primes
    }
  }
  let count = 0;
  for (let i = 2; i < n; i++) {
    if (isPrime[i]) count++;
  }
  return count;
}

def count_primes(n: int) -> int:
    if n < 3:
        return 0  # no primes below 2
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p < n:
        if is_prime[p]:
            for m in range(p * p, n, p):
                is_prime[m] = False  # smaller multiples were crossed out by smaller primes
        p += 1
    return sum(is_prime)

public int countPrimes(int n) {
    if (n < 3) return 0; // no primes below 2
    boolean[] isPrime = new boolean[n];
    Arrays.fill(isPrime, 2, n, true);
    for (int p = 2; p * p < n; p++) {
        if (!isPrime[p]) continue; // p is composite: its multiples are already crossed out
        for (int m = p * p; m < n; m += p) {
            isPrime[m] = false; // smaller multiples were crossed out by smaller primes
        }
    }
    int count = 0;
    for (boolean b : isPrime) if (b) count++;
    return count;
}

function reverse(x) {
  const MAX = 2147483647, MIN = -2147483648; // 32-bit signed range
  let rev = 0;
  while (x !== 0) {
    const digit = x % 10; // last digit (negative when x is negative)
    x = Math.trunc(x / 10); // drop it, rounding toward zero
    if (rev > Math.trunc(MAX / 10) || (rev === Math.trunc(MAX / 10) && digit > 7)) return 0;
    if (rev < Math.trunc(MIN / 10) || (rev === Math.trunc(MIN / 10) && digit < -8)) return 0;
    rev = rev * 10 + digit; // safe: checked before multiplying
  }
  return rev;
}

public int reverse(int x) {
    int rev = 0;
    while (x != 0) {
        int digit = x % 10; // last digit (negative when x is negative)
        x /= 10; // integer division truncates toward zero
        if (rev > Integer.MAX_VALUE / 10 || (rev == Integer.MAX_VALUE / 10 && digit > 7)) return 0;
        if (rev < Integer.MIN_VALUE / 10 || (rev == Integer.MIN_VALUE / 10 && digit < -8)) return 0;
        rev = rev * 10 + digit; // safe: checked before multiplying
    }
    return rev;
}

function getSum(a, b) {
  while (b !== 0) {
    const carry = (a & b) << 1; // columns where both bits are 1 carry left
    a = a ^ b;                  // add every column, ignoring carries
    b = carry;                  // add the carries in the next round
  }
  return a;
}

public int getSum(int a, int b) {
    while (b != 0) {
        int carry = (a & b) << 1; // columns where both bits are 1 carry left
        a = a ^ b;                // add every column, ignoring carries
        b = carry;                // add the carries in the next round
    }
    return a;
}

function reverseBits(n) {
  let res = 0;
  for (let i = 0; i < 32; i++) {
    res = (res << 1) | (n & 1);
    n >>>= 1;
  }
  return res >>> 0;
}

